using it.unive.lisa.symbolic.value.operator.binary;

public class PcodeBinaryExpression : it.unive.lisa.program.cfg.statement.BinaryExpression {

	private BinaryOperator operator;

	public PcodeBinaryExpression(
			CFG cfg,
			BinaryExprContext ctx,
			Expression left,
			Expression right) : base(cfg, ctx.location(), ctx.mnemonic(),
			cfg.getDescriptor().getUnit().getProgram().getTypes().getIntegerType(), left, right)
    {

		this.operator = switch (ctx.op.getOpcode()) {
			case PcodeOp.BOOL_AND: return LogicalAnd.INSTANCE;
			case PcodeOp.BOOL_OR: return LogicalOr.INSTANCE;
			case PcodeOp.INT_EQUAL, PcodeOp.FLOAT_EQUAL: return ComparisonEq.INSTANCE;
			case PcodeOp.INT_NOTEQUAL, PcodeOp.FLOAT_NOTEQUAL: return ComparisonNe.INSTANCE;
			case PcodeOp.INT_LESSEQUAL, PcodeOp.INT_SLESSEQUAL, PcodeOp.FLOAT_LESSEQUAL: return ComparisonLe.INSTANCE;
			// NB: Some chance we're going to get burned by including SBORROW here
			case PcodeOp.INT_LESS, PcodeOp.INT_SLESS, PcodeOp.INT_SBORROW, PcodeOp.FLOAT_LESS: return ComparisonLt.INSTANCE;
			default: new PcodeBinaryOperator(ctx.op);
		};
	}

	/* @Override */
	protected int compareSameClassAndParams(
			Statement o) {
		return 0; // no extra fields to compare
	}

	/* @Override */
	public AnalysisState<A> fwdBinarySemantics<A>/* where A : AbstractState<A> */(
			InterproceduralAnalysis<A> interprocedural,
			AnalysisState<A> state,
			SymbolicExpression left,
			SymbolicExpression right,
			StatementStore<A> expressions)
    {

		return state.smallStepSemantics(
			new BinaryExpression(
				getStaticType(),
				left,
				right,
				getOperator(),
				getLocation()),
			this);
	}

	public BinaryOperator getOperator() {
		return operator;
	}
}
